import { useState } from 'react';
import { JxCalendar, JxChip } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
};

const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());

const shiftDays = (days: number) => {
  const base = startOfDay(new Date());
  base.setDate(base.getDate() - days);
  return base;
};

const presets = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week', label: 'Неделя назад', days: 7 },
];

const isSameDay = (a: Date | null | undefined, b: Date) =>
  a != null && startOfDay(a).getTime() === b.getTime();

export default function ReportDatePicker({ value, defaultValue = null, onChange }: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(defaultValue);
  const selectedDate = value !== undefined ? value : internalDate;

  const selectDate = (next: Date | null) => {
    if (value === undefined) {
      setInternalDate(next);
    }
    onChange?.(next);
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', fontFamily: 'var(--jx-font-sans)' }}>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
        {presets.map((preset) => {
          const presetDate = shiftDays(preset.days);
          return (
            <JxChip
              key={preset.id}
              active={isSameDay(selectedDate, presetDate)}
              onClick={() => selectDate(presetDate)}
            >
              {preset.label}
            </JxChip>
          );
        })}
      </div>
      <JxCalendar locale="ru-RU" value={selectedDate} onValueChange={selectDate} />
    </div>
  );
}

